import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In Euclidean space of dimension {dimension}, consider three convex sets K_1, K_2, K_3. A point p is called encapsulated if there exists a sufficiently small radius r > 0 such that every point of the punctured ball B(p, r) \\ {p} lies in K_1 ∪ K_2 ∪ K_3. A point p contacts a convex set K if p ∉ K but every neighborhood of p contains points of K (equivalently, p is a boundary point of K). Let T be the set of encapsulated points that contact all three sets simultaneously (i.e., lie on the boundary of each K_i). Over all choices of three convex sets in ℝ^{ {dimension} }, determine g({dimension}) = max |T|.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose a reasonably large dimension to make the instance nontrivial
# Ensure d >= 2 so the triple-contact phenomenon is meaningful
d = rng.randint(2, 50)
# Return the assignment dictionary
return {'dimension': d}

    def verifier(assign):
# Validate domain constraints and compute the answer.
# The problem asks for g(d) where d = assign['dimension'].
# g(d) is the maximum number of encapsulated points that contact all three convex sets in R^d.
# Result: g(d) = floor(3(d-1)/2) + 1.
try:
    d = assign.get('dimension', None)
    if not isinstance(d, int):
        # Invalid type
        return (False, None)
    if d < 2:
        # The family enforces d >= 2 for nontrivial geometry
        return (False, None)
    # Compute the answer
    ans = (3 * (d - 1)) // 2 + 1
    return (True, ans)
except Exception:
    # Any unexpected error marks invalid
    return (False, None)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

